package org.springframework.samples.petclinic.blackbox.security;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.hamcrest.Matchers.notNullValue;
import static io.restassured.RestAssured.given;

/**
 * Black-Box API Integration Test
 *
 * @target-controller AuthController (src/main/java/org/springframework/samples/petclinic/security/AuthController.java)
 * @target-api POST /api/auth/login
 *
 * No DB dependency: CustomUserDetailsService authenticates against hardcoded users
 * ("admin"/"password", "user"/"password"), so no setup/teardown SQL is required.
 * No external HTTP dependency was found by detect-external-calls, so no WireMock stub is required.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String API_PATH = "/api/auth/login";

	private static final String JWT_PATTERN = "^[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+$";

	private static String loginBody(Object username, Object password) {
		String usernameJson = username == null ? "null" : "\"" + username + "\"";
		String passwordJson = password == null ? "null" : "\"" + password + "\"";
		return "{\"username\":" + usernameJson + ",\"password\":" + passwordJson + "}";
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	void NTC_login_admin_success() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody("admin", "password"))
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(200)
			.contentType(ContentType.JSON)
			.body("token", matchesPattern(JWT_PATTERN))
			.body("type", equalTo("Bearer"))
			.body("username", equalTo("admin"))
			.body("expiresIn", equalTo(86400));
	}

	@Test
	void NTC_login_user_success() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody("user", "password"))
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(200)
			.contentType(ContentType.JSON)
			.body("token", matchesPattern(JWT_PATTERN))
			.body("type", equalTo("Bearer"))
			.body("username", equalTo("user"))
			.body("expiresIn", equalTo(86400));
	}

	@Test
	void NTC_login_admin_tokenValidatesSuccessfully() {
		String token = given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody("admin", "password"))
		.when()
			.post(API_PATH)
		.then()
			.statusCode(200)
			.body("token", notNullValue())
			.extract().path("token");

		// End-to-end verification that the issued token is a genuinely usable JWT
		given().log().all()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + token)
		.when()
			.post("/api/auth/validate")
		.then().log().all()
			.statusCode(200)
			.contentType(ContentType.JSON)
			.body("valid", equalTo(true))
			.body("username", equalTo("admin"));
	}

	// ===================== VTC (Validation — RED param: username) =====================

	@Test
	void VTC_username_NULL() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody(null, "password"))
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.contentType(ContentType.JSON)
			.body("error", equalTo("Invalid username or password"));
	}

	@Test
	void VTC_username_EMPTY() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody("", "password"))
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.contentType(ContentType.JSON)
			.body("error", equalTo("Invalid username or password"));
	}

	@Test
	void VTC_username_WHITE_SPACE() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody("   ", "password"))
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.contentType(ContentType.JSON)
			.body("error", equalTo("Invalid username or password"));
	}

	@Test
	void VTC_username_SPECIAL_CHAR() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody("'; DROP TABLE users--", "password"))
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.contentType(ContentType.JSON)
			.body("error", equalTo("Invalid username or password"));
	}

	// ===================== ATC (Exception) =====================

	@Test
	void ATC_username_unknown_invalidCredentials() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody("does-not-exist", "password"))
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.contentType(ContentType.JSON)
			.body("error", equalTo("Invalid username or password"));
	}

	@Test
	void ATC_password_wrong_invalidCredentials() {
		given().log().all()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body(loginBody("admin", "wrong-password"))
		.when()
			.post(API_PATH)
		.then().log().all()
			.statusCode(400)
			.contentType(ContentType.JSON)
			.body("error", equalTo("Invalid username or password"));
	}

}

