package org.springframework.samples.petclinic.blackbox.owner;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.greaterThan;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller OwnerRestController (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api POST /api/owners
 *
 * Auth: /api/owners is matched by SecurityConfig's "/api/**".authenticated() rule, so a
 * valid JWT (obtained from POST /api/auth/login) is required in the Authorization header.
 * No external HTTP dependency was found by detect-external-calls, so no WireMock stub is used.
 *
 * createOwner has NO @Valid on the request body and the "owners" DDL columns have no
 * NOT NULL / length constraints beyond the MySQL varchar column widths, so field-level
 * bean-validation errors are NOT possible here; see .nimbus/artifacts/test-plan and
 * .nimbus/artifacts/vtc-plan for OwnerRestController_createOwner for the source analysis
 * this test plan is grounded in.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ApiOwnersCreateBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	private static final String API_PATH = "/api/owners";

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	/** Logs in as the given hardcoded user (CustomUserDetailsService) and returns a bearer JWT. */
	private static String obtainToken(String username, String password) {
		return given()
				.baseUri(BASE_URL)
				.contentType(ContentType.JSON)
				.body("{\"username\":\"" + username + "\",\"password\":\"" + password + "\"}")
		.when()
				.post("/api/auth/login")
		.then()
				.statusCode(200)
				.extract().path("token");
	}

	private static void deleteOwnerById(int ownerId) throws Exception {
		try (Connection conn = getDbConnection();
				PreparedStatement ps = conn.prepareStatement("DELETE FROM owners WHERE id = ?")) {
			ps.setInt(1, ownerId);
			ps.executeUpdate();
		}
	}

	private static String ownerBody(String firstName, String lastName, String address, String city,
			String telephone) {
		return "{"
				+ "\"firstName\":" + jsonString(firstName) + ","
				+ "\"lastName\":" + jsonString(lastName) + ","
				+ "\"address\":" + jsonString(address) + ","
				+ "\"city\":" + jsonString(city) + ","
				+ "\"telephone\":" + jsonString(telephone)
				+ "}";
	}

	private static String jsonString(String value) {
		if (value == null) {
			return "null";
		}
		return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	void NTC_createOwner_success_georgeFranklin() throws Exception {
		String token = obtainToken("admin", "password");
		int createdId = -1;
		try {
			var response = given().log().all()
					.baseUri(BASE_URL)
					.header("Authorization", "Bearer " + token)
					.contentType(ContentType.JSON)
					.body(ownerBody("George", "NimbusFranklin", "110 W. Liberty St.", "Madison", "6085551023"))
			.when()
					.post(API_PATH)
			.then().log().all()
					.statusCode(201)
					.contentType(ContentType.JSON)
					.body("id", greaterThan(0))
					.body("firstName", equalTo("George"))
					.body("lastName", equalTo("NimbusFranklin"))
					.body("address", equalTo("110 W. Liberty St."))
					.body("city", equalTo("Madison"))
					.body("telephone", equalTo("6085551023"))
					.extract();
			createdId = response.path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT first_name, last_name, address, city, telephone FROM owners WHERE id = ?")) {
				ps.setInt(1, createdId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals("George", rs.getString("first_name"));
					assertEquals("NimbusFranklin", rs.getString("last_name"));
					assertEquals("110 W. Liberty St.", rs.getString("address"));
					assertEquals("Madison", rs.getString("city"));
					assertEquals("6085551023", rs.getString("telephone"));
				}
			}
		}
		finally {
			if (createdId > 0) {
				deleteOwnerById(createdId);
			}
		}
	}

	@Test
	void NTC_createOwner_success_secondOwner() throws Exception {
		String token = obtainToken("user", "password");
		int createdId = -1;
		try {
			var response = given().log().all()
					.baseUri(BASE_URL)
