				+ "\"lastName\":" + jsonString(lastName) + ","
				+ "\"address\":" + jsonString(address) + ","
				+ "\"city\":" + jsonString(city) + ","
				+ "\"telephone\":" + jsonString(telephone)
				+ "}";
	}

	private static String jsonString(String value) {
		if (value == null) {
			return "null";
		}
		return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
	}

