			.when()
					.put("/api/owners/" + ownerId)
			.then().log().all()
					.statusCode(200)
					.contentType(ContentType.JSON)
					.body("id", equalTo(ownerId))
					.body("firstName", equalTo("UpdatedFirst"))
					.body("lastName", equalTo("UpdatedLast"))
					.body("address", equalTo("42 Updated Ave."))
					.body("city", equalTo("Updateville"))
					.body("telephone", equalTo("5551234567"));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT first_name, last_name, address, city, telephone FROM owners WHERE id = ?")) {
				ps.setInt(1, ownerId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals("UpdatedFirst", rs.getString("first_name"));
					assertEquals("UpdatedLast", rs.getString("last_name"));
					assertEquals("42 Updated Ave.", rs.getString("address"));
					assertEquals("Updateville", rs.getString("city"));
					assertEquals("5551234567", rs.getString("telephone"));
				}
			}
		}
		finally {
			executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		}
	}

	@Test
	void NTC_updateOwner_success_idInBodyOverriddenByPathVariable(TestInfo info) throws Exception {
		int ownerId = ownerTestId(info);
		String token = obtainToken("admin", "password");
		executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		executeSqlTemplate("sql/api-owners-update-setup.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		try {
			// Body carries a bogus id far outside the reserved test range; controller
			// unconditionally overwrites it with the path variable via owner.setId(ownerId).
			given().log().all()
					.baseUri(BASE_URL)
					.header("Authorization", "Bearer " + token)
					.contentType(ContentType.JSON)
					.body(ownerBody(999999999, "BodyIdIgnored", "BodyIdIgnored", "1 Nowhere Rd.", "Nowhere",
							"1230004567"))
			.when()
					.put("/api/owners/" + ownerId)
			.then().log().all()
					.statusCode(200)
					.body("id", equalTo(ownerId));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT id FROM owners WHERE id = ?")) {
				ps.setInt(1, ownerId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals(ownerId, rs.getInt("id"));
				}
				try (PreparedStatement ps2 = conn.prepareStatement("SELECT COUNT(*) FROM owners WHERE id = 999999999")) {
					try (ResultSet rs2 = ps2.executeQuery()) {
						assertTrue(rs2.next());
						assertEquals(0, rs2.getInt(1));
					}
				}
			}
		}
		finally {
			executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		}
	}

	@Test
	void NTC_updateOwner_success_boundaryLengthFields(TestInfo info) throws Exception {
