					.body("city", equalTo(city))
					.body("telephone", equalTo(telephone));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT first_name, city, telephone FROM owners WHERE id = ?")) {
				ps.setInt(1, ownerId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals(firstName, rs.getString("first_name"));
					assertEquals(city, rs.getString("city"));
					assertEquals(telephone, rs.getString("telephone"));
				}
			}
		}
		finally {
			executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		}
	}

	// ===================== VTC (Validation) =====================

	@Test
	void VTC_ownerId_INVALID_FORMAT() {
		String token = obtainToken("admin", "password");
		// ownerId path variable fails Integer conversion before the handler runs
		// (MethodArgumentTypeMismatchException), independent of any DB state.
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.contentType(ContentType.JSON)
				.body(ownerBody(null, "X", "Y", "Z", "Z", "0000000000"))
		.when()
				.put("/api/owners/not-a-number")
		.then().log().all()
				.statusCode(400);
	}

	@Test
	void VTC_lastName_WHITE_SPACE(TestInfo info) throws Exception {
		int ownerId = ownerTestId(info);
		String token = obtainToken("admin", "password");
		executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		executeSqlTemplate("sql/api-owners-update-setup.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		try {
			given().log().all()
					.baseUri(BASE_URL)
					.header("Authorization", "Bearer " + token)
					.contentType(ContentType.JSON)
					.body(ownerBody(null, "Whitespace", "   ", "1 Test St.", "Testville", "1112223333"))
			.when()
					.put("/api/owners/" + ownerId)
			.then().log().all()
					.statusCode(200)
					.body("lastName", equalTo("   "));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT last_name FROM owners WHERE id = ?")) {
				ps.setInt(1, ownerId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals("   ", rs.getString("last_name"));
				}
			}
		}
		finally {
			executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		}
	}

	@Test
	void VTC_lastName_SPECIAL_CHAR(TestInfo info) throws Exception {
		int ownerId = ownerTestId(info);
		String token = obtainToken("admin", "password");
		String injection = "'; DROP TABLE owners; --";
		executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		executeSqlTemplate("sql/api-owners-update-setup.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		try {
			given().log().all()
					.baseUri(BASE_URL)
					.header("Authorization", "Bearer " + token)
					.contentType(ContentType.JSON)
					.body(ownerBody(null, "Injection", injection, "1 Test St.", "Testville", "1112223334"))
			.when()
					.put("/api/owners/" + ownerId)
			.then().log().all()
					.statusCode(200)
					.body("lastName", equalTo(injection));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT last_name FROM owners WHERE id = ?")) {
				ps.setInt(1, ownerId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals(injection, rs.getString("last_name"));
				}
			}
		}
		finally {
			executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		}
	}

	// ===================== ATC (Exception) =====================

	@Test
	void ATC_ownerId_noData(TestInfo info) {
		int ownerId = ownerTestId(info);
		String token = obtainToken("admin", "password");
		// No setup: this id is intentionally left absent from the owners table.
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.contentType(ContentType.JSON)
				.body(ownerBody(null, "Nobody", "Nobody", "Nowhere", "Nowhere", "0000000000"))
		.when()
				.put("/api/owners/" + ownerId)
		.then().log().all()
				.statusCode(404);
	}

	@Test
	void ATC_owner_null_serverError(TestInfo info) throws Exception {
		int ownerId = ownerTestId(info);
		String token = obtainToken("admin", "password");
		executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		executeSqlTemplate("sql/api-owners-update-setup.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		try {
			// ownerId exists (passes existsById), but a null body causes owner.setId(ownerId)
			// to throw a NullPointerException with no handler to catch it.
			given().log().all()
					.baseUri(BASE_URL)
					.header("Authorization", "Bearer " + token)
					.contentType(ContentType.JSON)
					.body("null")
			.when()
					.put("/api/owners/" + ownerId)
			.then().log().all()
					.statusCode(500);
		}
		finally {
			executeSqlTemplate("sql/api-owners-update-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		}
	}

	@Test
	void ATC_malformedJson_badRequest(TestInfo info) {
		int ownerId = ownerTestId(info);
		String token = obtainToken("admin", "password");
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.contentType(ContentType.JSON)
				.body("{\"firstName\": \"Broken\", }")
		.when()
				.put("/api/owners/" + ownerId)
		.then().log().all()
				.statusCode(400);
	}

}

