package org.springframework.samples.petclinic.blackbox.owner;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.greaterThan;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller PetRestController (src/main/java/org/springframework/samples/petclinic/owner/PetRestController.java)
 * @target-api POST /api/pets
 *
 * Auth: /api/pets is matched by SecurityConfig's "/api/**".authenticated() rule, so a
 * valid JWT (obtained from POST /api/auth/login) is required in the Authorization header.
 * No external HTTP dependency was found by detect-external-calls, so no WireMock stub is used.
 *
 * createPet(@RequestBody Pet pet, Integer ownerId) has NO annotation on ownerId; Spring MVC
 * resolves an unannotated simple-type controller parameter as an implicit, REQUIRED request
 * parameter, so it must be supplied as a query string parameter (?ownerId=...), not JSON body
 * or path variable. There is also no @Valid, so no bean-validation errors are possible on the
 * Pet body itself.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ApiPetsCreateBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	private static final String API_PATH = "/api/pets";

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	/** Deterministic per-method id in a range reserved for this test file (920000-929999). */
	private static int ownerTestId(TestInfo info) {
		return 920000 + (Math.abs(info.getTestMethod().get().getName().hashCode()) % 10000);
	}

	private static String obtainToken(String username, String password) {
		return given()
				.baseUri(BASE_URL)
				.contentType(ContentType.JSON)
				.body("{\"username\":\"" + username + "\",\"password\":\"" + password + "\"}")
		.when()
				.post("/api/auth/login")
		.then()
				.statusCode(200)
				.extract().path("token");
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = ApiPetsCreateBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (var entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	private static void deletePetById(int petId) throws Exception {
		try (Connection conn = getDbConnection();
				PreparedStatement ps = conn.prepareStatement("DELETE FROM pets WHERE id = ?")) {
			ps.setInt(1, petId);
			ps.executeUpdate();
		}
	}

	private static String petBody(String name, String birthDate, int typeId, String typeName) {
		return "{\"name\":\"" + name + "\",\"birthDate\":\"" + birthDate + "\",\"type\":{\"id\":" + typeId
				+ ",\"name\":\"" + typeName + "\"}}";
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	void NTC_createPet_success_cat(TestInfo info) throws Exception {
		int ownerId = ownerTestId(info);
		String token = obtainToken("admin", "password");
		executeSqlTemplate("sql/api-pets-create-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		executeSqlTemplate("sql/api-pets-create-setup.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		int createdPetId = -1;
		try {
			var response = given().log().all()
					.baseUri(BASE_URL)
					.header("Authorization", "Bearer " + token)
					.contentType(ContentType.JSON)
					.queryParam("ownerId", ownerId)
					.body(petBody("Whiskers", "2020-01-01", 1, "cat"))
			.when()
					.post(API_PATH)
			.then().log().all()
					.statusCode(201)
					.contentType(ContentType.JSON)
					.body("id", greaterThan(0))
					.body("name", equalTo("Whiskers"))
					.body("birthDate", equalTo("2020-01-01"))
					.body("type.id", equalTo(1))
					.body("type.name", equalTo("cat"))
					.extract();
			createdPetId = response.path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT name, birth_date, type_id, owner_id FROM pets WHERE id = ?")) {
				ps.setInt(1, createdPetId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals("Whiskers", rs.getString("name"));
					assertEquals("2020-01-01", rs.getDate("birth_date").toLocalDate().toString());
					assertEquals(1, rs.getInt("type_id"));
					assertEquals(ownerId, rs.getInt("owner_id"));
				}
			}
		}
		finally {
			if (createdPetId > 0) {
				deletePetById(createdPetId);
			}
			executeSqlTemplate("sql/api-pets-create-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		}
	}

	@Test
	void NTC_createPet_success_dog(TestInfo info) throws Exception {
		int ownerId = ownerTestId(info);
		String token = obtainToken("user", "password");
		executeSqlTemplate("sql/api-pets-create-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		executeSqlTemplate("sql/api-pets-create-setup.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		int createdPetId = -1;
		try {
			var response = given().log().all()
					.baseUri(BASE_URL)
					.header("Authorization", "Bearer " + token)
					.contentType(ContentType.JSON)
					.queryParam("ownerId", ownerId)
					.body(petBody("Rex", "2018-06-15", 2, "dog"))
			.when()
					.post(API_PATH)
			.then().log().all()
					.statusCode(201)
					.contentType(ContentType.JSON)
					.body("id", greaterThan(0))
					.body("name", equalTo("Rex"))
					.body("birthDate", equalTo("2018-06-15"))
					.body("type.id", equalTo(2))
					.body("type.name", equalTo("dog"))
					.extract();
			createdPetId = response.path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT name, type_id, owner_id FROM pets WHERE id = ?")) {
				ps.setInt(1, createdPetId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals("Rex", rs.getString("name"));
					assertEquals(2, rs.getInt("type_id"));
					assertEquals(ownerId, rs.getInt("owner_id"));
				}
			}
		}
		finally {
			if (createdPetId > 0) {
				deletePetById(createdPetId);
			}
			executeSqlTemplate("sql/api-pets-create-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
		}
	}

	@Test
	void NTC_createPet_success_boundaryNameLength(TestInfo info) throws Exception {
