package org.springframework.samples.petclinic.blackbox.vet;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

/**
 * Black-Box API Integration Test
 *
 * @target-controller VetController (src/main/java/org/springframework/samples/petclinic/vet/VetController.java)
 * @target-api GET /vets
 *
 * Auth: /vets is NOT under "/api/**"; SecurityConfig's final rule is anyRequest().permitAll(),
 * so this endpoint requires no Authorization header (verified directly against SecurityConfig,
 * since analyze-auth-flow's endpoint-agnostic interceptor scan cannot see the authorizeHttpRequests
 * URL-pattern matching and over-flags Authorization as required for every endpoint).
 *
 * Read-only endpoint over data.sql seed data (vets/specialties/vet_specialties); no request
 * parameters, no external HTTP dependency (detect-external-calls found none), so no setup/
 * teardown SQL or WireMock stub is required.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class VetsBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String API_PATH = "/vets";

	// ===================== NTC (Happy Path) =====================

	@Test
	void NTC_getVets_success_returnsAllSeedVets() {
		given().log().all()
				.baseUri(BASE_URL)
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.contentType(ContentType.JSON)
				.body("vetList.size()", equalTo(6))
				.body("vetList.find { it.id == 1 }.firstName", equalTo("James"))
				.body("vetList.find { it.id == 1 }.lastName", equalTo("Carter"))
				.body("vetList.find { it.id == 6 }.firstName", equalTo("Sharon"))
				.body("vetList.find { it.id == 6 }.lastName", equalTo("Jenkins"));
	}

	@Test
	void NTC_getVets_success_explicitJsonAccept() {
		given().log().all()
				.baseUri(BASE_URL)
				.accept(ContentType.JSON)
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.contentType(ContentType.JSON)
				.body("vetList.size()", equalTo(6))
				.body("vetList.find { it.id == 2 }.firstName", equalTo("Helen"))
				.body("vetList.find { it.id == 2 }.specialties.size()", equalTo(1))
				.body("vetList.find { it.id == 2 }.specialties[0].name", equalTo("radiology"));
	}

	@Test
	void NTC_getVets_success_specialtiesSortedAlphabetically() {
		// Linda Douglas (id=3) has both "surgery" and "dentistry"; Vet#getSpecialties()
		// sorts by name, so the response must list "dentistry" before "surgery".
		given().log().all()
				.baseUri(BASE_URL)
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.body("vetList.find { it.id == 3 }.lastName", equalTo("Douglas"))
				.body("vetList.find { it.id == 3 }.nrOfSpecialties", equalTo(2))
				.body("vetList.find { it.id == 3 }.specialties[0].name", equalTo("dentistry"))
				.body("vetList.find { it.id == 3 }.specialties[1].name", equalTo("surgery"));
	}

	// ===================== ATC (Exception) =====================

	@Test
	void ATC_unsupportedAccept_notAcceptable() {
		// No converter can satisfy an Accept header outside JSON/XML for this endpoint,
		// so Spring MVC responds with 406 rather than serializing anything.
		given().log().all()
				.baseUri(BASE_URL)
				.accept("application/pdf")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(406);
	}

}

