package org.springframework.samples.petclinic.blackbox.vet;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

/**
 * Black-Box API Integration Test
 *
 * @target-controller VetRestController (src/main/java/org/springframework/samples/petclinic/vet/VetRestController.java)
 * @target-api GET /api/vets
 *
 * Auth: /api/vets is matched by SecurityConfig's "/api/**".authenticated() rule, so a valid
 * JWT (obtained from POST /api/auth/login) is required in the Authorization header.
 *
 * Read-only endpoint over data.sql seed data; no external HTTP dependency was found by
 * detect-external-calls, so no WireMock stub and no setup/teardown SQL are required.
 * getAllVets's only real request parameter is the optional "specialty" query string filter
 * (RestController_getAllVets RED param per generate-vtc-from-red-params); a reported
 * "isEmpty" parameter in that skill's output does not correspond to any actual parameter of
 * this method and is not a real branch, so no test is generated for it.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ApiVetsListBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String API_PATH = "/api/vets";

	private static String obtainToken(String username, String password) {
		return given()
				.baseUri(BASE_URL)
				.contentType(ContentType.JSON)
				.body("{\"username\":\"" + username + "\",\"password\":\"" + password + "\"}")
		.when()
				.post("/api/auth/login")
		.then()
				.statusCode(200)
				.extract().path("token");
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	void NTC_getAllVets_success_noFilterReturnsAllSix() {
		String token = obtainToken("admin", "password");
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.contentType(ContentType.JSON)
				.body("size()", equalTo(6))
				.body("find { it.id == 1 }.firstName", equalTo("James"))
				.body("find { it.id == 4 }.lastName", equalTo("Ortega"));
	}

	@Test
	void NTC_getAllVets_success_filterBySpecialty_radiology() {
		String token = obtainToken("user", "password");
		// radiology is held by Helen Leary (id=2) and Henry Stevens (id=5) per data.sql.
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.queryParam("specialty", "radiology")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.contentType(ContentType.JSON)
				.body("size()", equalTo(2))
				.body("collect { it.id }.sort()", equalTo(java.util.List.of(2, 5)));
	}

	@Test
	void NTC_getAllVets_success_filterCaseInsensitivePartialMatch() {
		String token = obtainToken("admin", "password");
		// "DENT" (uppercase, partial) must still match "dentistry" (Linda Douglas, id=3)
		// via vet.getSpecialties().stream().anyMatch(name.toLowerCase().contains(...)).
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.queryParam("specialty", "DENT")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.body("size()", equalTo(1))
				.body("[0].id", equalTo(3))
				.body("[0].lastName", equalTo("Douglas"));
	}

	// ===================== VTC =====================

	@Test
	void VTC_specialty_EMPTY_behavesAsNoFilter() {
		String token = obtainToken("admin", "password");
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.queryParam("specialty", "")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.body("size()", equalTo(6));
	}

	@Test
	void VTC_specialty_noMatchingSpecialty_returnsEmptyList() {
		String token = obtainToken("admin", "password");
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.queryParam("specialty", "nonexistent-specialty-xyz")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.body("size()", equalTo(0));
	}

	// ===================== ATC (Exception) =====================

	@Test
	void ATC_missingAuth_forbidden() {
		// No Authorization header at all against a "/api/**".authenticated() endpoint;
		// SecurityConfig registers no custom AuthenticationEntryPoint, so Spring Security's
		// default (Http403ForbiddenEntryPoint) applies.
		given().log().all()
				.baseUri(BASE_URL)
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(403);
	}

	@Test
	void ATC_invalidToken_forbidden() {
		// JwtAuthenticationFilter catches the parse failure, logs it, and never populates
		// the SecurityContext, so the request reaches the filter chain unauthenticated.
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer not-a-valid-jwt")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(403);
	}

}

