		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.queryParam("specialty", "")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.body("size()", equalTo(6));
	}

	@Test
	void VTC_specialty_noMatchingSpecialty_returnsEmptyList() {
		String token = obtainToken("admin", "password");
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
				.queryParam("specialty", "nonexistent-specialty-xyz")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(200)
				.body("size()", equalTo(0));
	}

	// ===================== ATC (Exception) =====================

	@Test
	void ATC_missingAuth_forbidden() {
		// No Authorization header at all against a "/api/**".authenticated() endpoint;
		// SecurityConfig registers no custom AuthenticationEntryPoint, so Spring Security's
		// default (Http403ForbiddenEntryPoint) applies.
		given().log().all()
				.baseUri(BASE_URL)
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(403);
	}

	@Test
	void ATC_invalidToken_forbidden() {
		// JwtAuthenticationFilter catches the parse failure, logs it, and never populates
		// the SecurityContext, so the request reaches the filter chain unauthenticated.
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer not-a-valid-jwt")
		.when()
				.get(API_PATH)
		.then().log().all()
				.statusCode(403);
	}

}

