package org.springframework.samples.petclinic.blackbox.vet;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

/**
 * Black-Box API Integration Test
 *
 * @target-controller VetRestController (src/main/java/org/springframework/samples/petclinic/vet/VetRestController.java)
 * @target-api GET /api/vets/{vetId}
 *
 * Auth: /api/vets/** is matched by SecurityConfig's "/api/**".authenticated() rule, so a
 * valid JWT (obtained from POST /api/auth/login) is required in the Authorization header.
 * No external HTTP dependency was found by detect-external-calls, so no WireMock stub and
 * no setup/teardown SQL are required (read-only over data.sql seed data).
 *
 * getVet's return type is plain Vet (not ResponseEntity&lt;Vet&gt;) and its implementation is
 * `vetRepository.findAll().stream().filter(...).findFirst().orElse(null)`. When no vet matches,
 * the handler returns a null Java value; Spring's RequestResponseBodyMethodProcessor writes
 * nothing for a null return value, so the response is 200 OK with an EMPTY body -- not 404.
 * This is verified directly against the controller source, not assumed.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ApiVetsDetailBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static String obtainToken(String username, String password) {
		return given()
				.baseUri(BASE_URL)
				.contentType(ContentType.JSON)
				.body("{\"username\":\"" + username + "\",\"password\":\"" + password + "\"}")
		.when()
				.post("/api/auth/login")
		.then()
				.statusCode(200)
				.extract().path("token");
	}

	// ===================== NTC (Happy Path) =====================

	@Test
	void NTC_getVet_success_vetWithOneSpecialty() {
		String token = obtainToken("admin", "password");
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
		.when()
				.get("/api/vets/2")
		.then().log().all()
				.statusCode(200)
				.contentType(ContentType.JSON)
				.body("id", equalTo(2))
				.body("firstName", equalTo("Helen"))
				.body("lastName", equalTo("Leary"))
				.body("nrOfSpecialties", equalTo(1))
				.body("specialties[0].name", equalTo("radiology"));
	}

	@Test
	void NTC_getVet_success_vetWithMultipleSpecialtiesSorted() {
		String token = obtainToken("user", "password");
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
		.when()
				.get("/api/vets/3")
		.then().log().all()
				.statusCode(200)
				.body("id", equalTo(3))
				.body("firstName", equalTo("Linda"))
				.body("lastName", equalTo("Douglas"))
				.body("nrOfSpecialties", equalTo(2))
				.body("specialties[0].name", equalTo("dentistry"))
				.body("specialties[1].name", equalTo("surgery"));
	}

	@Test
	void NTC_getVet_success_vetWithNoSpecialties() {
		String token = obtainToken("admin", "password");
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
		.when()
				.get("/api/vets/1")
		.then().log().all()
				.statusCode(200)
				.body("id", equalTo(1))
				.body("firstName", equalTo("James"))
				.body("lastName", equalTo("Carter"))
				.body("nrOfSpecialties", equalTo(0))
				.body("specialties.size()", equalTo(0));
	}

	// ===================== VTC =====================

	@Test
	void VTC_vetId_zero_noMatch_emptyBody() {
		String token = obtainToken("admin", "password");
		// vetId=0 is a well-formed Integer but never matches a seeded vet id; getVet()
		// falls through to orElse(null), yielding 200 with a zero-length body.
		String body = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
		.when()
				.get("/api/vets/0")
		.then().log().all()
				.statusCode(200)
				.extract().asString();
		org.junit.jupiter.api.Assertions.assertEquals("", body);
	}

	@Test
	void VTC_vetId_INVALID_FORMAT() {
		String token = obtainToken("admin", "password");
		// vetId path variable fails Integer conversion before the handler runs.
		given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
		.when()
				.get("/api/vets/not-a-number")
		.then().log().all()
				.statusCode(400);
	}

	// ===================== ATC (Exception) =====================

	@Test
	void ATC_vetId_noData_returns200WithEmptyBody() {
		String token = obtainToken("admin", "password");
		// A syntactically valid but nonexistent id (999999): same null-return path as
		// VTC_vetId_zero above. Documented separately because it is the checklist item
		// this test plan is built against (generate-test-plan: ATC_vetId_noData), and
		// because a naive implementation would assume 404 here -- it is actually 200.
		String body = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + token)
		.when()
				.get("/api/vets/999999")
		.then().log().all()
				.statusCode(200)
				.extract().asString();
		org.junit.jupiter.api.Assertions.assertEquals("", body);
	}

	@Test
	void ATC_missingAuth_forbidden() {
		given().log().all()
				.baseUri(BASE_URL)
		.when()
				.get("/api/vets/1")
		.then().log().all()
				.statusCode(403);
	}

}

